entries[93168] = { ["name"] = "Grand Armored Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Grand Armored Gryphon mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Operation: Shieldwall\n- Exalted\nSell Price:\n\"This noble gryphon is as staunch a battle companion as any member of the Alliance could ask for.\"\nVendor:\nAgent Malley\nZone:\nKrasarang Wilds\nFaction:\nOperation: Shieldwall - Exalted\nCost:" }
entries[93169] = { ["name"] = "Grand Armored Wyvern", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Grand Armored Wyvern mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Dominance Offensive\n- Exalted\nSell Price:\n\"This ferocious beast, renowned among wyvern handlers, was one of the first mounts chosen to take part in the Horde's Dominance Offensive.\"\nVendor:\nTuskripper Grukna\nZone:\nKrasarang Wilds\nFaction:\nDominance Offensive - Exalted\nCost:" }
