entries[93385] = { ["name"] = "Grand Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Grand Gryphon mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Gryphons' keen eyesight allows them to see over vast distances and warn their riders of any dangers that lie ahead.\"\nQuest:\nThe Silence\nZone:\nKun-Lai Summit" }
entries[93386] = { ["name"] = "Grand Wyvern", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Grand Wyvern mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Wyverns hail from some of the most inhospitable regions of Kalimdor, making them masters of adapting to any environment.\"\nQuest:\nBreath of Darkest Shadow\nZone:\nKun-Lai Summit" }
