entries[93655] = { ["name"] = "Kirin Tor Agent's Badge", ["text"] = "Binds when picked up\n\"Ripped off of the armor of a dead Kirin Tor agent. The Sunreavers will reward you for this.\"" }
entries[93656] = { ["name"] = "Sunreaver Agent's Badge", ["text"] = "Binds when picked up\n\"Ripped off of the armor of a dead Sunreaver agent. The Kirin Tor will reward you for this.\"" }
entries[93660] = { ["name"] = "Thunder-Laced Egg", ["text"] = "Binds when picked up\n\"A peculiar cloud serpent egg, jolts of electricity spark across the surface.\"" }
entries[93662] = { ["name"] = "Reins of the Armored Skyscreamer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Armored Skyscreamer. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only those heroic souls who surmount every challenge the mogu tyrants place before them can proudly fly the skies on a war-prepared skyscreamer.\"\nAchievement:\nGlory of the Thundering Raider\nCategory:\nDungeons & Raids" }
entries[93666] = { ["name"] = "Spawn of Horridon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When you see a hurricane coming, you get out of the way. Horridon would fight the hurricane and win.\"\nDrop:\nHorridon\nZone:\nThrone of Thunder" }
entries[93668] = { ["name"] = "Saur Fetish", ["text"] = "Quest Item\nUse: Use this fetish on a raptor, saurid, skyscreamer, or direhorn in the Beast Pens to attempt to assert your control over them. Results may be unpredictable. (10 Sec Cooldown)" }
entries[93669] = { ["name"] = "Gusting Grimoire", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss a Gusting Grimoire.\nRequires level 1 to 80 ( 80)" }
entries[93671] = { ["name"] = "Ghastly Charger's Skull", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Ghastly Charger. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Not all of Medivh's victims are gone for good.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
entries[93672] = { ["name"] = "Dark Portal", ["text"] = "Binds when picked up\nToy\nUse: Returns you to Hearthstone Location. Speak to an Innkeeper in a different place to change your home location.\n\"BEHOLD, THE DARK PORTAL. Well, a tiny version, at any rate.\"" }
