entries[93730] = { ["name"] = "Darkmoon Top Hat", ["text"] = "Binds when picked up\nUnique (20)\nUse: Increase experience and reputation gains by 10% for 1 hour. Hat is consumed on use.\nRequires Darkmoon Faire\nSell Price:" }
entries[93731] = { ["name"] = "Mogu Codex Fragment", ["text"] = "Quest Item\n\"Contains a portion of the Arcane Code blocking the entrance to the Zandalari Shipyard.\"" }
entries[93732] = { ["name"] = "Darkmoon Fishing Cap", ["text"] = "Binds when picked up\nUnique\nHead\nUse: Summon a pool of Shipwrecked Debris. Requires the Darkmoon Faire to be open. (1 Hour Cooldown)\nEquip: On Equip: +5 Fishing Skill.\nSell Price:" }
entries[93733] = { ["name"] = "Mask of the Spirit-Caller", ["text"] = "Quest Item\nUnique\n\"Carefully carved, this mask surges with the power of the serpent Loa for which it represents.\"" }
entries[93734] = { ["name"] = "Mask of the Dark Mystic", ["text"] = "Quest Item\nUnique\n\"The magic within the mask is fickle. It honors only the strong and seeks to destroy the weak.\"" }
entries[93735] = { ["name"] = "Ritual Artifact", ["text"] = "Quest Item\n\"Who knows what dark magic this artifact was intended for...\"" }
entries[93736] = { ["name"] = "Loa-Infused Blade", ["text"] = "Quest Item\n\"Specks of blood are barely visible through the ornate designs covering the blade and hilt of this weapon.\"" }
entries[93738] = { ["name"] = "Rusty Prison Key", ["text"] = "Binds when picked up" }
entries[93742] = { ["name"] = "Healing Potion", ["text"] = "Scenario Item\nUse: Restores 25% of your maximum health. (5 Min Cooldown)" }
entries[93751] = { ["name"] = "Blessed Torch", ["text"] = "Quest Item\nUse: Burn the mummified remains of a mogu. (2 Sec Cooldown)" }
entries[93761] = { ["name"] = "Arcane Emancipator", ["text"] = "Quest Item\nUse: Releases a trapped scout within 15 yds. from Mogu Wards and teleports them to safety." }
entries[93792] = { ["name"] = "Head of the Chamberlain", ["text"] = "Quest Item\n\"This mogu head continuously mocks you for your woefully inadequate stature.\"" }
entries[93793] = { ["name"] = "Shoulder of the Chamberlain", ["text"] = "Quest Item\n\"One false move and this stone will crumble to dust in your hands.\"" }
entries[93794] = { ["name"] = "Staff of the Chamberlain", ["text"] = "Quest Item\n\"This stone weapon looks more ceremonial than functional.\"" }
entries[93795] = { ["name"] = "Hair of the Chamberlain", ["text"] = "Quest Item\n\"There isn't much of this left.\"" }
entries[93796] = { ["name"] = "Torso of the Chamberlain", ["text"] = "Quest Item\n\"For some reason, this is much lighter than it looks.\"" }
entries[93803] = { ["name"] = "Incantation of Gura", ["text"] = "Quest Item\nUse: Call a creature from beyond the grave. Use near the final resting place of Gura the Reclaimed. (3 Sec Cooldown)" }
entries[93805] = { ["name"] = "Sunreaver Scout Report", ["text"] = "Quest Item\n\"Details Kirin Tor movements and numbers across the isle.\"" }
entries[93806] = { ["name"] = "Resonance Siphon", ["text"] = "Quest Item\nUnique\nUse: Can be used to siphon the weakened Zandalari soul from within the sentry corpse. (5 Sec Cooldown)" }
