entries[93900] = { ["name"] = "Inherited Mark of Tyranny", ["text"] = "Binds to Warband\nUnique\nTrinket\nUse: Increases maximum health by 0 for 15 sec. Shares cooldown with other Battlemaster's trinkets. (2 Min Cooldown)" }
