entries[93955] = { ["name"] = "Zandalari Spiritbinder Scrimshaw", ["text"] = "Binds when picked up\n\"An intricately carved serpent wraps its way around a large snake fang.\"\nSell Price:" }
entries[93956] = { ["name"] = "Zandalari Venomancer Scrimshaw", ["text"] = "Binds when picked up\n\"This engraved spider fang still has the venom sac attached, presumably for ritual poisoning.\"\nSell Price:" }
entries[93957] = { ["name"] = "Zandalari Beastlord Scrimshaw", ["text"] = "Binds when picked up\n\"The ornamented tip of this spear is carved from the rack of a Direhorn's skull.\"\nSell Price:" }
entries[93958] = { ["name"] = "Pilfered Mogu Urn", ["text"] = "Binds when picked up\n\"The Saurok have repurposed this priceless, ten-thousand-year-old ceramic in to a chamber pot.\"\nSell Price:" }
entries[93959] = { ["name"] = "Skumblade Jeweled Cockroach", ["text"] = "Binds when picked up\n\"Large, roughly cut gems are clumsily glued to each wing of this still-wiggling cockroach.\"\nSell Price:" }
