entries[94228] = { ["name"] = "Reins of the Cobalt Primordial Direhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"When ya fight alongside raptors, ya want a mount dey can't eat.\" -Unknown dinomancer\nDrop:\nOondasta\nLocation:\nIsle of Giants" }
entries[94229] = { ["name"] = "Reins of the Slate Primordial Direhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The masks aren't to control the direhorn; they are so no one sees your face when it turns on you.\"\nDrop:\nZandalari Warbringer\nZone:\nDread Wastes, Krasarang Wilds, Kun-Lai Summit, Townlong Steppes, Valley of the Four Winds" }
entries[94230] = { ["name"] = "Reins of the Amber Primordial Direhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"There is an old Zandalari saying about wild direhorns: \"Run!\"\"\nDrop:\nZandalari Warbringer\nZone:\nDread Wastes, Kun-Lai Summit, Townlong Steppes, Valley of the Four Winds" }
